solution.solution.cpp:
#include <utility>
#include <vector>

class List
{
public:
    struct Node { int value; Node* prev; Node* next; };

    List() { sentinel.prev = &sentinel; sentinel.next = &sentinel; }
    ~List()
    {
        Node* n{ sentinel.next };
        while (n != &sentinel) { Node* next{ n->next }; delete n; n = next; }
    }
    List(const List&) = delete;
    List& operator=(const List&) = delete;

    Node* pushFront(int value) { return insertBefore(sentinel.next, value); }
    Node* pushBack(int value) { return insertBefore(&sentinel, value); }

    Node* insertBefore(Node* where, int value)
    {
        Node* n{ new Node{ value, where->prev, where } };
        where->prev->next = n;
        where->prev = n;
        ++count;
        return n;
    }

    void remove(Node* node)
    {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        delete node;
        --count;
    }

    void reverse()
    {
        Node* n{ &sentinel };
        do
        {
            std::swap(n->prev, n->next);
            n = n->prev;           // after the swap, prev is the old next
        } while (n != &sentinel);
    }

    int size() const { return count; }

    std::vector<int> values() const
    {
        std::vector<int> out;
        for (const Node* n{ sentinel.next }; n != &sentinel; n = n->next) out.push_back(n->value);
        return out;
    }

    std::vector<int> valuesBackwards() const
    {
        std::vector<int> out;
        for (const Node* n{ sentinel.prev }; n != &sentinel; n = n->prev) out.push_back(n->value);
        return out;
    }

private:
    Node sentinel{ 0, nullptr, nullptr };
    int count{ 0 };
};

unitTests:
using V = std::vector<int>;
TEST("push at both ends") {
    List list;
    CHECK_EQ(list.size(), 0);
    CHECK_EQ(list.values(), V{});
    list.pushBack(2); list.pushBack(3); list.pushFront(1);
    CHECK_EQ(list.values(), (V{ 1, 2, 3 }));
    CHECK_EQ(list.valuesBackwards(), (V{ 3, 2, 1 }));
    CHECK_EQ(list.size(), 3);
}
TEST("nodes keep their addresses") {
    List list;
    List::Node* a{ list.pushBack(10) };
    List::Node* c{ list.pushBack(30) };
    List::Node* b{ list.insertBefore(c, 20) };
    for (int i{ 0 }; i < 100; ++i) list.pushBack(i);
    CHECK_EQ(a->value, 10); CHECK_EQ(b->value, 20); CHECK(a->next == b); CHECK(b->next == c);
    list.remove(b);
    CHECK(a->next == c); CHECK(c->prev == a);
    CHECK_EQ(list.size(), 102);
}
TEST("remove first, last and only") {
    List list;
    List::Node* only{ list.pushBack(7) };
    list.remove(only);
    CHECK_EQ(list.values(), V{});
    List::Node* first{ list.pushBack(1) };
    list.pushBack(2);
    List::Node* last{ list.pushBack(3) };
    list.remove(first); list.remove(last);
    CHECK_EQ(list.values(), (V{ 2 }));
    CHECK_EQ(list.valuesBackwards(), (V{ 2 }));
}
TEST("reverse") {
    List list;
    for (int i{ 1 }; i <= 5; ++i) list.pushBack(i);
    list.reverse();
    CHECK_EQ(list.values(), (V{ 5, 4, 3, 2, 1 }));
    CHECK_EQ(list.valuesBackwards(), (V{ 1, 2, 3, 4, 5 }));
    list.pushBack(0);
    CHECK_EQ(list.values(), (V{ 5, 4, 3, 2, 1, 0 }));
    List empty;
    empty.reverse();
    CHECK_EQ(empty.values(), V{});
}

